# Auto-setup script for Course Portal Site
import os, base64

FILES_B64 = {'README.md': '', 'build.el': '', '.github/workflows/deploy.yml': '', 'src/index.org': '', 'src/guidance.org': '', 'src/github-account-and-org.org': '', 'src/repository-and-codespaces.org': '', 'src/syllabus.org': '', 'src/evaluation/rubric.org': '', 'src/evaluation/self-checklist.org': '', 'src/guides/f12-debugging.org': '', 'src/guides/troubleshooting.org': '', 'src/prompts/copilot-prompts.org': '', 'src/teacher/orientation-slides.org': '', 'src/teacher/teacher-guidance.org': '', 'src/prompts/lesson01-prompts.org': '', 'src/prompts/lesson02-prompts.org': '', 'src/prompts/lesson03-prompts.org': '', 'src/prompts/lesson04-prompts.org': '', 'src/prompts/lesson05-prompts.org': '', 'src/prompts/lesson06-prompts.org': '', 'src/prompts/lesson07-prompts.org': '', 'src/prompts/lesson08-prompts.org': '', 'src/prompts/lesson09-prompts.org': '', 'src/prompts/lesson10-prompts.org': '', 'src/prompts/lesson11-prompts.org': '', 'src/prompts/lesson12-prompts.org': '', 'src/prompts/lesson13-prompts.org': '', 'src/prompts/lesson14-prompts.org': '', 'src/prompts/lesson15-prompts.org': ''}

def main():
    print("=== 2026年度プログラミング中級 ポータルサイト 一括生成スクリプト ===")
    created_count = 0
    for rel_path, b64_str in FILES_B64.items():
        dir_name = os.path.dirname(rel_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        content = base64.b64decode(b64_str.encode("ascii"))
        with open(rel_path, "wb") as f:
            f.write(content)
        print(f" [作成完了] {rel_path}")
        created_count += 1
    print(f"\n完了! 合計 {created_count} 個のファイルとフォルダ構造を復元しました。")

if __name__ == "__main__":
    main()
